import { createTheme } from "@mui/material/styles";

export const lightTheme = createTheme({
  palette: {
    primary: {
      main: "#006060",
    },
    secondary: {
      main: "#ebcea0",
    },
    background: {
      default: "#f0f0d8",
    },
  },
  typography: {
    fontFamily: "Metrophonic, sans-serif",
  },
});

export const darkTheme = createTheme({
  palette: {
    primary: {
      main: "#003030",
    },
    secondary: {
      main: "#ebcea0",
    },
    background: {
      default: "#121212",
    },
  },
  typography: {
    fontFamily: "Metrophonic, sans-serif",
  },
});

export default lightTheme;
